from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Initialize an empty list to store the separated groups
    separated_groups = []

    # Step 3: Iterate through the input string and identify individual sets of nested parentheses
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count == 0:
                separated_groups.append(paren_string[start:i+1])
                start = i + 1

    # Step 4: Check if each set of parentheses is balanced and not nested within each other
    valid_groups = []
    for group in separated_groups:
        stack = []
        is_valid = True
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    is_valid = False
                    break
        if is_valid and not stack:
            valid_groups.append(group)

    # Step 6: Return the list of separated groups
    return valid_groups

